const news = $input.first().json;
const style = news.style || 'balanced';
const sentences = news.sentences || 3;

const styleMap = {
  balanced: 'Ты умный и немного ироничный новостной комментатор. Пиши живо, без пресности.',
  ironic: 'Ты саркастичный аналитик. Пиши с легкой иронией и остроумием.',
  ironictrump: 'Ты саркастичный аналитик. Пиши с легкой иронией и остроумием. Особенно ты любишь угорать над Трампом, Путиным, пророссийскими коррупционерами и депутами из Украины, Тцк',
  serious: 'Ты серьезный эксперт-аналитик. Пиши авторитетно и по делу.'
};

const systemPrompt = styleMap[style] || styleMap.ironictrump;

const userContent = 'Прочитай эту новость и напиши комментарий на русском языке: '
  + sentences + ' предложений. Только текст, без заголовков и кавычек.\n\n'
  + 'Заголовок: ' + (news.title || '') + '\n'
  + 'Текст: ' + (news.content || '').substring(0, 500) + '\n'
  + 'Источник: ' + (news.source || '');

return [{
  json: {
    model: 'gemma-4-e4b',
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userContent }
    ],
    temperature: 0.7,
    max_tokens: 2048
  }
}];

const news = $('When called by another workflow').first().json;
const msg = $input.first().json?.choices?.[0]?.message || {};
// content only: falling back to reasoning_content would post the model's chain of thought
const aiComment = (msg.content || '').trim();

const title = (news.title || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const content = (news.content || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const comment = aiComment.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const url = news.url || '';
const source = news.source || 'Источник';

const commentBlock = comment ? '\n\n💬 <i>' + comment + '</i>' : '';

const text = '<b>' + title + '</b>\n\n'
  + content
  + commentBlock
  + '\n\n<a href="' + url + '">' + source + '</a>';

return [{ json: { text } }];
